passages:
{'acquirer': [{'quote': 'On May 21, 2023, PDC Energy, Inc. (“PDC”), Chevron Corporation (“Chevron”) and Bronco Merger Sub Inc., a direct, wholly-owned subsidiary of Chevron (“Merger Subsidiary”), entered into a merger agreement under which, upon the terms and subject to the conditions set forth therein, Merger Subsidiary will merge with and into PDC, with PDC surviving as a direct, wholly-owned subsidiary of Chevron (the “merger”).', 'location': 'DEFM14A, TRANSACTION PROPOSED-YOUR VOTE IS VERY IMPORTANT'}], 'target': [{'quote': 'The merger agreement contains the terms and conditions of the proposed acquisition of PDC by Chevron.', 'location': 'DEFM14A, QUESTIONS AND ANSWERS ABOUT THE MERGER AND THE SPECIAL MEETING, page 1'}, {'quote': 'PDC Energy, Inc. (“PDC”), Chevron Corporation (“Chevron”) and Bronco Merger Sub Inc., a direct, wholly-owned subsidiary of Chevron (“Merger Subsidiary”)', 'location': 'DEFM14A, TRANSACTION PROPOSED-YOUR VOTE IS VERY IMPORTANT'}], 'consideration_type': [{'quote': 'In the merger, each share of PDC common stock that is issued and outstanding immediately prior to the effective time of the merger (other than cancelled shares) will be converted into the right to receive the merger consideration, consisting of 0.4638 of a validly issued, fully paid and non-assessable share of Chevron common stock.', 'location': 'DEFM14A, SUMMARY—Merger Consideration, page 12'}, {'quote': 'No fractional shares of Chevron common stock will be issued in connection with the merger. Each holder of PDC common stock that otherwise would have been entitled to receive a fractional share of Chevron common stock immediately prior to the effective time of the merger will have the right to receive an amount in cash, without interest, rounded to the nearest cent, in lieu of such fractional share.', 'location': 'DEFM14A, SUMMARY—Merger Consideration, page 12'}], 'cash_consideration': [{'quote': 'Each holder of PDC common stock that otherwise would have been entitled to receive a fractional share of Chevron common stock immediately prior to the effective time of the merger will have the right to receive an amount in cash, without interest, rounded to the nearest cent, in lieu of such fractional share. The value of such cash payment will be calculated by the exchange agent and will represent the holder’s proportionate interest in a trust of proceeds established from the open-market sale of that number of shares of Chevron common stock equal to the excess of (i) the aggregate number of shares of Chevron common stock to be delivered to the exchange agent by Chevron pursuant to the terms of the merger agreement over (ii) the aggregate number of whole shares of Chevron common stock to be distributed to the holders of certificates or book-entry shares previously representing any such shares of PDC common stock pursuant to the merger agreement.', 'location': 'DEFM14A, SUMMARY—Merger Consideration, page 12'}, {'quote': 'The parties acknowledge that payment of the cash consideration in lieu of issuing fractional shares was not separately bargained-for consideration but merely represents a mechanical rounding off for purposes of avoiding the expense and inconvenience to Parent that would otherwise be caused by the issuance of fractional shares.', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 2.2(a), page A-7'}], 'stock_exchange_ratio': [{'quote': 'At the Effective Time, subject to the other provisions of Articles I and II, each share of Company Common Stock issued and outstanding immediately prior to the Effective Time (other than shares of Company Common Stock to be canceled pursuant to Section 1.4(d) and any shares of Company Common Stock covered under Section 1.5) shall, by virtue of the Merger and without any action on the part of the holder thereof, be converted into and shall thereafter represent the right to receive 0.4638 (the “Exchange Ratio”) of a share of validly issued, fully paid and non-assessable shares of Parent Common Stock (the “Merger Consideration”).', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 1.4(a), page A-3'}, {'quote': 'The exchange ratio is fixed and will not be adjusted to reflect changes in the stock price of either company prior to the closing of the merger. The exchange ratio will, however, be adjusted appropriately to fully reflect the effect of any reclassification, recapitalization, stock split or combination, exchange or readjustment of shares, or any stock dividend thereon, with respect to outstanding shares of capital stock of either Chevron or PDC with a record date between the date of the merger agreement and the completion of the merger.', 'location': 'DEFM14A, SUMMARY—Merger Consideration, page 12'}, {'quote': 'No such adjustment will be made for cash dividends or grants of equity compensation not prohibited by the merger agreement.', 'location': 'DEFM14A, THE MERGER AGREEMENT—Merger Consideration—Potential Adjustment to Merger Consideration, page 75'}, {'quote': 'PDC stockholders will not receive any fractional shares of Chevron common stock pursuant to the merger. Each holder of PDC common stock that otherwise would have been entitled to receive a fractional share of Chevron common stock at the effective time of the merger will receive an amount in cash, without interest, rounded to the nearest cent, in lieu of such fractional share.', 'location': 'DEFM14A, THE MERGER AGREEMENT—Merger Consideration—Treatment of Fractional Shares, page 74'}, {'quote': 'common stock, par value $0.75 per share, of Chevron (“Chevron common stock”)', 'location': 'DEFM14A, ABOUT THIS PROXY STATEMENT/PROSPECTUS, page ii'}, {'quote': 'common stock, par value $0.01 per share, of the Company (the “Company Common Stock”)', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, recitals, page A-1'}], 'shareholder_vote_date': [{'quote': 'The special meeting of PDC stockholders will be held virtually at www.virtualshareholdermeeting.com/PDCE2023SM, on August 4, 2023, at 8:00 a.m., Mountain Time.', 'location': 'DEFM14A, SPECIAL MEETING—Date, Time and Place, page 100'}, {'quote': 'the merger proposal—a proposal to adopt the merger agreement, a copy of which is attached as Annex A to this proxy statement/prospectus', 'location': 'DEFM14A, SPECIAL MEETING—Purpose of the Special Meeting, page 100'}], 'closing_conditions': [{'quote': 'The obligations of the Company, Parent and Merger Subsidiary to consummate the Merger are subject to the satisfaction (or, to the extent permitted by law, waiver) of the following conditions:', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 8.1, page A-53'}, {'quote': '(a) this Agreement shall have been adopted by the stockholders of the Company in accordance with the DGCL;
(b) any applicable waiting period under the HSR Act relating to the Merger shall have expired or been terminated;
(c) no provision of any applicable law or regulation and no judgment, injunction, order or decree shall prohibit or enjoin the consummation of the Merger;
(d) the Form S-4 shall have been declared effective by the SEC under the Securities Act and no stop order suspending the effectiveness of the Form S-4 shall be in effect and no proceedings for such purpose shall be pending before or threatened by the SEC; and
(e) the shares of Parent Common Stock to be issued in the Merger shall have been approved for listing on the NYSE, subject to official notice of issuance.', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 8.1, page A-53'}, {'quote': 'The waiting period under the HSR Act expired on July 5, 2023.', 'location': 'DEFM14A, Regulatory Approvals Required for the Merger, page 65'}, {'quote': 'The obligations of Parent and Merger Subsidiary to consummate the Merger are subject to the satisfaction (or, to the extent permitted by law, waiver) of the following further conditions:', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 8.2, page A-53'}, {'quote': '(a) (i) The Company shall have performed in all material respects all of its obligations hereunder required to be performed by it as of or prior to the Closing Date and (ii) (A) the representations and warranties of the Company set forth in Section 3.11(b) of this Agreement shall be true and correct in all respects at and as of the date of this Agreement and at and as of the Closing Date as though made at and as of the date of this Agreement and at and as of the Closing Date, (B) the representations and warranties of the Company set forth in the first two sentences of Section 3.5 shall be true and correct at and as of the Closing Date as though made at and as of the Closing Date except for De Minimis Inaccuracies, (C) the representations and warranties of the Company set forth in Section 3.5 (other than the first two sentences thereof) shall be true and correct (disregarding all qualifications or limitations as to “material”, “materiality” or “Company Material Adverse Effect”) in all material respects at and as of the date of this Agreement and at and as of the Closing Date as though made at and as of the Closing Date, and (D) the representations and warranties of the Company set forth in Article III of this Agreement other than those described in the preceding clauses (A)-(C) shall be true and correct at and as of the date of this Agreement and at and as of the Closing Date as though made at and as of the Closing Date except where the failure to be so true and correct (disregarding all qualifications or limitations as to “material”, “materiality” or “Company Material Adverse Effect”) would not, individually or in the aggregate, reasonably be expected to have a Company Material Adverse Effect; provided, however, that, with respect to clauses (A), (B), (C), and (D) above, representations and warranties that are made as of a particular date or period shall be true and correct (consistent with the respective thresholds set forth in clause (A), (B), (C), or (D) as applicable) only as of such date or period.', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 8.2(a), pages A-53–A-54'}, {'quote': '(b) Parent shall have received a certificate of the Company, executed on its behalf by an authorized officer of the Company, dated the Closing Date, certifying that the conditions set forth in Section 8.2(a)(i) and Section 8.2(a)(ii) have been satisfied.', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 8.2(b), page A-54'}, {'quote': 'The obligation of the Company to consummate the Merger is subject to the satisfaction (or, to the extent permitted by law, waiver) of the following further conditions:', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 8.3, page A-54'}, {'quote': '(a) (i) Parent shall have performed in all material respects all of its obligations hereunder required to be performed by it as of or prior to the Closing Date and (ii) (A) the representations and warranties of Parent and Merger Subsidiary set forth in Section 4.10(b) of this Agreement shall be true and correct in all respects at and as of the Closing Date as though made at and as of the date of this Agreement and at and as of the Closing Date, (B) the representations and warranties of Parent and Merger Subsidiary set forth in the first two sentences of Section 4.5 shall be true and correct at and as of the date of this Agreement and at and as of the Closing Date as though made at and as of the Closing Date except for De Minimis Inaccuracies, (C) the representations and warranties of Parent and Merger Subsidiary set forth in Section 4.5 (other than the first two sentences thereof) shall be true and correct in all material respects at and as of the date of this Agreement and at and as of the Closing Date as though made at and as of the Closing Date, and (D) the representations and warranties of Parent and Merger Subsidiary set forth in Article IV of this Agreement other than those described in the preceding clauses (A)-(C) shall be true and correct (disregarding all qualifications or limitations as to “material”, “materiality” or “Parent Material Adverse Effect”) at and as of the date of this Agreement and at and as of the Closing Date as though made at and as of the Closing Date, except where the failure to be so true and correct would not, individually or in the aggregate, reasonably be expected to have a Parent Material Adverse Effect; provided, however, that, with respect to clauses (A), (B), (C) and (D) above, representations and warranties that are made as of a particular date or period shall be true and correct (consistent with the respective thresholds set forth in clause (A), (B), (C) or (D) as applicable) only as of such date or period.', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 8.3(a), page A-54'}, {'quote': '(b) The Company shall have received a certificate of Parent, executed on its behalf by an authorized officer of Parent, dated the Closing Date, certifying that the conditions set forth in Section 8.3(a)(i) and Section 8.3(a)(ii) have been satisfied.', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 8.3(b), page A-54'}, {'quote': 'Chevron’s obligations under the merger agreement are not subject to any condition regarding its ability to finance, or obtain financing for, the merger.', 'location': 'DEFM14A, QUESTIONS AND ANSWERS ABOUT THE MERGER AND THE SPECIAL MEETING, page 2'}, {'quote': 'The completion of the merger is not conditioned on the approval of the merger-related compensation proposal or the adjournment proposal.', 'location': 'DEFM14A, QUESTIONS AND ANSWERS ABOUT THE MERGER AND THE SPECIAL MEETING, page 3'}], 'event_status': [{'quote': 'Following the PDC Board meeting, PDC and Chevron executed the merger agreement.
Prior to the opening of trading on May 22, 2023, Chevron and PDC issued a joint press release announcing entry into the merger agreement.', 'location': 'DEFM14A, THE MERGER—Background of the Merger, page 40'}, {'quote': 'The waiting period under the HSR Act expired on July 5, 2023.', 'location': 'DEFM14A, Regulatory Approvals Required for the Merger, page 65'}, {'quote': 'The merger cannot be completed without approval of the proposal to adopt the merger agreement by the affirmative vote of holders of a majority of the outstanding shares of PDC common stock entitled to vote thereon. Because of this, PDC is holding a special meeting of its stockholders on August 4, 2023 to vote on the proposal necessary to complete the merger.', 'location': 'DEFM14A, TRANSACTION PROPOSED-YOUR VOTE IS VERY IMPORTANT'}, {'quote': 'This proxy statement/prospectus is dated July 7, 2023, and is first being mailed to stockholders of PDC on or about July 7, 2023.', 'location': 'DEFM14A, TRANSACTION PROPOSED-YOUR VOTE IS VERY IMPORTANT'}], 'security_description': [{'quote': 'common stock, par value $0.01 per share, of the Company (the “Company Common Stock”)', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, recitals, page A-1'}, {'quote': 'At the Effective Time, subject to the other provisions of Articles I and II, each share of Company Common Stock issued and outstanding immediately prior to the Effective Time (other than shares of Company Common Stock to be canceled pursuant to Section 1.4(d) and any shares of Company Common Stock covered under Section 1.5)', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 1.4(a), page A-3'}, {'quote': 'At the effective time of the merger, all shares of PDC common stock that are owned directly by Chevron, Merger Subsidiary or PDC will be cancelled and retired and will cease to exist and no stock of Chevron, cash or other consideration will be delivered in exchange therefor.', 'location': 'DEFM14A, THE MERGER AGREEMENT—Merger Consideration—Cancelled Shares, page 74'}], 'effective_date': [{'quote': 'On the Closing Date, immediately after the Closing, the Company will file a certificate of merger with respect to the Merger with the Secretary of State of the State of Delaware (the “Certificate of Merger”) and the parties shall make all other filings or recordings required by the DGCL in connection with the Merger. The Merger shall become effective at such time as the Certificate of Merger is duly filed with the Secretary of State of the State of Delaware or at such later time as Parent and the Company may agree and is specified in the Certificate of Merger (the “Effective Time”).', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 1.1(b), page A-2'}], 'available_options': [{'quote': 'At the Effective Time, subject to the other provisions of Articles I and II, each share of Company Common Stock issued and outstanding immediately prior to the Effective Time (other than shares of Company Common Stock to be canceled pursuant to Section 1.4(d) and any shares of Company Common Stock covered under Section 1.5) shall, by virtue of the Merger and without any action on the part of the holder thereof, be converted into and shall thereafter represent the right to receive 0.4638 (the “Exchange Ratio”) of a share of validly issued, fully paid and non-assessable shares of Parent Common Stock (the “Merger Consideration”).', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 1.4(a), page A-3'}, {'quote': 'No fractional shares of Parent Common Stock shall be issued in the Merger, but in lieu thereof each holder of shares of Company Common Stock otherwise entitled to a fractional share of Parent Common Stock will be entitled to receive, from the Exchange Agent in accordance with the provisions of this Section 2.2 and subject to the provisions of Section 2.1, a cash payment (without interest and rounded to the nearest cent) in lieu of such fractional shares of Parent Common Stock', 'location': 'DEFM14A, Annex A—Agreement and Plan of Merger, Section 2.2(a), page A-7'}], 'default_option': [], 'election_deadline': []}

{'acquirer': [{'quote': 'On May 14, 2023, ONEOK and Magellan entered into an Agreement and Plan of Merger (the “Merger Agreement”) with Otter Merger Sub, LLC, a wholly owned subsidiary of ONEOK (“Merger Sub”), pursuant to which Merger Sub will merge with and into Magellan (the “merger”), with Magellan surviving the merger as a direct wholly owned subsidiary of ONEOK.', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}, {'quote': 'Unless the context otherwise requires, all references in this joint proxy statement/prospectus to “ONEOK” refer to ONEOK, Inc., an Oklahoma corporation. Unless the context otherwise requires, all references in this joint proxy statement/prospectus to “Magellan” refer to Magellan Midstream Partners, L.P., a Delaware limited partnership.', 'location': 'fs42023a1_oneokinc.htm, ADDITIONAL INFORMATION'}], 'target': [{'quote': 'On May 14, 2023, ONEOK and Magellan entered into an Agreement and Plan of Merger (the “Merger Agreement”) with Otter Merger Sub, LLC, a wholly owned subsidiary of ONEOK (“Merger Sub”), pursuant to which Merger Sub will merge with and into Magellan (the “merger”), with Magellan surviving the merger as a direct wholly owned subsidiary of ONEOK.', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}, {'quote': 'Unless the context otherwise requires, all references in this joint proxy statement/prospectus to “Magellan” refer to Magellan Midstream Partners, L.P., a Delaware limited partnership.', 'location': 'fs42023a1_oneokinc.htm, ADDITIONAL INFORMATION'}], 'consideration_type': [{'quote': 'subject to certain terms of the Merger Agreement, each Magellan Unit issued and outstanding (other than Excluded Units) immediately prior to the Effective Time will automatically be converted into and will thereafter represent the right to receive from ONEOK 0.667 duly authorized and validly issued shares of ONEOK Common Stock and $25.00 in cash.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Merger Consideration, page 102'}, {'quote': 'If after the date of the Merger Agreement and at or prior to the Effective Time, any change in the outstanding Magellan Units or outstanding ONEOK Common Stock occurs as a result of any reclassification, stock or unit split (including a reverse stock or unit split) or combination, exchange or readjustment of shares or units, or any stock or unit dividend or stock or unit distribution with a record date during such period, the Merger Consideration, the Cash Consideration, the Equity Consideration, the Exchange Ratio, the Equity Exchange Ratio and any other similarly dependent items will be equitably adjusted to eliminate the effect of such event on such items and provide to ONEOK, Merger Sub and the Magellan unitholders the same economic effect as contemplated by the Merger Agreement prior to such event.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Adjustments to Exchange Ratio, page 105'}], 'cash_consideration': [{'quote': 'subject to certain terms of the Merger Agreement, each Magellan Unit issued and outstanding (other than Excluded Units) immediately prior to the Effective Time will automatically be converted into and will thereafter represent the right to receive from ONEOK 0.667 duly authorized and validly issued shares of ONEOK Common Stock and $25.00 in cash.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Merger Consideration, page 102'}, {'quote': 'The amount of cash payable in respect of each Magellan Unit as specified in the second bullet above (as number may be adjusted in accordance with the terms of the Merger Agreement) is referred to as the Cash Consideration, and together with the Equity Consideration, is referred to as the Merger Consideration.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Merger Consideration, page 102'}, {'quote': 'Each holder of Magellan Units converted in the merger who would otherwise have been entitled to receive a fraction of a shares of ONEOK Common Stock (after taking into account all Magellan Units exchanged by such holder) will receive, in lieu thereof, cash (without interest rounded up to the nearest whole cent) in an amount equal to the product of (i) the volume-weighted average closing price of one share of ONEOK Common Stock as reported on the NYSE for the ten (10) consecutive full trading days (in which shares of ONEOK Common Stock are traded on the NYSE) ending at the close of trading on the full trading day immediately preceding (and not including) the closing date and (ii) the fraction of a share of ONEOK Common Stock that such holder would otherwise be entitled to receive under the Merger Agreement.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Exchange of Shares — Fractional Shares, page 104'}, {'quote': 'If after the date of the Merger Agreement and at or prior to the Effective Time, any change in the outstanding Magellan Units or outstanding ONEOK Common Stock occurs as a result of any reclassification, stock or unit split (including a reverse stock or unit split) or combination, exchange or readjustment of shares or units, or any stock or unit dividend or stock or unit distribution with a record date during such period, the Merger Consideration, the Cash Consideration, the Equity Consideration, the Exchange Ratio, the Equity Exchange Ratio and any other similarly dependent items will be equitably adjusted to eliminate the effect of such event on such items and provide to ONEOK, Merger Sub and the Magellan unitholders the same economic effect as contemplated by the Merger Agreement prior to such event.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Adjustments to Exchange Ratio, page 105'}], 'stock_exchange_ratio': [{'quote': 'In the merger, the holders of common units representing a limited partner interest in Magellan (each such common unit, a “Magellan Unit,” and each such holder, a “Magellan unitholder”) will receive, for each Magellan Unit that they own as of immediately prior to the effective time of the merger (the “Effective Time”), a combination of (i) $25.00 in cash (the “Cash Consideration”), and (ii) 0.667 (the “Exchange Ratio”) of a share of common stock of ONEOK, par value $0.01 per share (“ONEOK Common Stock”; such consideration, the “Equity Consideration” and together with the Cash Consideration, the “Merger Consideration”).', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}, {'quote': 'The Exchange Ratio is fixed (subject to adjustments in accordance with the terms of the Merger Agreement), which means that it will not change between now and the Effective Time, regardless of changes in the market price of ONEOK Common Stock and Magellan Units.', 'location': 'fs42023a1_oneokinc.htm, SUMMARY — Merger Consideration, page 2'}, {'quote': 'No certificates or scrip of ONEOK Common Stock representing fractional shares of ONEOK Common Stock or book-entry credit of the same will be issued upon the surrender of Magellan Units, and such fractional interests will not entitle the owner thereof to vote or to have any rights as a holder of ONEOK Common Stock.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Merger Consideration, page 102'}, {'quote': 'If after the date of the Merger Agreement and at or prior to the Effective Time, any change in the outstanding Magellan Units or outstanding ONEOK Common Stock occurs as a result of any reclassification, stock or unit split (including a reverse stock or unit split) or combination, exchange or readjustment of shares or units, or any stock or unit dividend or stock or unit distribution with a record date during such period, the Merger Consideration, the Cash Consideration, the Equity Consideration, the Exchange Ratio, the Equity Exchange Ratio and any other similarly dependent items will be equitably adjusted to eliminate the effect of such event on such items and provide to ONEOK, Merger Sub and the Magellan unitholders the same economic effect as contemplated by the Merger Agreement prior to such event.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Adjustments to Exchange Ratio, page 105'}], 'shareholder_vote_date': [{'quote': 'The ONEOK Special Meeting will be held virtually on September 21, 2023 at 9:00 a.m., Central Time.', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}, {'quote': 'At the ONEOK Special Meeting, ONEOK shareholders will be asked to consider and vote on proposals to (i) approve the issuance of shares of ONEOK Common Stock to the Magellan unitholders in connection with the merger', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}, {'quote': 'The Magellan Special Meeting will be held virtually on September 21, 2023, at 10:00 a.m., Central Time.', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}, {'quote': 'At the Magellan Special Meeting, Magellan unitholders will be asked to consider and vote on proposals to (i) approve the Merger Agreement (the “Merger Proposal”) and (ii) approve, on a non-binding advisory basis, the compensation that may be paid or become payable to Magellan GP’s named executive officers that is based on or otherwise relates to the merger (the “Non-Binding Advisory Compensation Proposal”).', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}], 'closing_conditions': [{'quote': 'Each party’s obligation to effect the merger is subject to the satisfaction at closing, or waiver at or prior to closing, of each of the following conditions:
• the approval of the Merger Proposal by the Magellan unitholders;
• the approval of the Stock Issuance Proposal by the ONEOK shareholders;
• the NYSE having approved the listing of the shares of ONEOK Common Stock to be issued in the merger, subject to official notice of issuance;
• the absence of any applicable law or order prohibiting or making illegal the consummation of the merger or the other transactions contemplated by the Merger Agreement;
• the expiration or termination of the waiting period under the HSR Act applicable to the transactions contemplated by the Merger Agreement and any agreement with any governmental entity not to effect the transactions contemplated by the Merger Agreement; and
• the registration statement on Form S-4, of which this joint proxy statement/prospectus forms a part, will have become effective under the Securities Act and no stop order suspending the effectiveness of the registration statement shall have been issued by the SEC, nor have proceedings seeking a stop order been initiated or threatened by the SEC.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Conditions to the Completion of the Merger, page 125'}, {'quote': '• the accuracy of the representations and warranties of Magellan as follows:
• the representations and warranties of Magellan regarding organization and certain representations regarding capital stock (as set forth in Section 3.2(a) and Section 3.2(f) of the Merger Agreement) shall be true and correct as of the date of the Merger Agreement and as of the closing date, as if made as of such date (except to the extent expressly made as of an earlier date, in which case only as of such date), except for immaterial inaccuracies;
• the representations and warranties of Magellan regarding operation in the ordinary course of business and the absence of a material adverse effect (as set forth in Section 3.10(b) and 3.10(c) of the Merger Agreement) shall be true and correct as of the date of the Merger Agreement and as of the closing date, as if made as of such date or period (except to the extent expressly made as of an earlier date, in which case only as of such date or period); and
• the representations and warranties of Magellan (other than Sections 3.2(a), 3.2(f), 3.10(b) and 3.10(c) of the Merger Agreement) shall be true and correct as of the date of the Merger Agreement and as of the closing date (except to the extent expressly made as of an earlier date, in which case only as of such date), except where the failure of such representations and warranties to be so true and correct (without giving effect to any limitation as to “materiality” or “material adverse effect” set forth in any individual such representation or warranty) would not, in the aggregate, reasonably be expected to have a material adverse effect on Magellan.
• Magellan’s performance or compliance in all material respects with all of its covenants, obligations or agreements required to be performed or complied with under the Merger Agreement prior to the Effective Time; and
• Magellan having delivered to ONEOK a certificate of a duly authorized officer certifying the matters of the immediately preceding bullets.
• Magellan having received an opinion of Latham & Watkins LLP, dated as of the closing date, in form and substance reasonably acceptable to ONEOK, to the effect that for U.S. federal income tax purposes (i) Magellan is properly classified as a partnership, and not as an association or a publicly traded partnership taxable as a corporation under Section 7704 of the Code and (ii) each subsidiary of Magellan is properly classified as (A) an entity disregarded as separate from Magellan or (B) a partnership, and not as an association or a publicly traded partnership taxable as a corporation under Section 7704 of the Code.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Conditions to the Completion of the Merger, pages 125–126'}, {'quote': '• the accuracy of the representations and warranties of ONEOK and Merger Sub as follows:
• the representations and warranties of ONEOK and Merger Sub regarding organization and certain representations regarding capital stock (as set forth in Section 4.2(a) and Section 4.2(g) of the Merger Agreement) shall be true and correct as of the date of the Merger Agreement and as of the closing date, as if made as of such date (except to the extent expressly made as of an earlier date, in which case only as of such date), except for immaterial inaccuracies;
• the representations and warranties of ONEOK and Merger Sub regarding operation in the ordinary course of business and the absence of a material adverse effect (as set forth in Section 4.10(b) and 4.10(c) of the Merger Agreement) shall be true and correct as of the date of the Merger Agreement and as of the closing date, as if made as of such date or period (except to the extent expressly made as of an earlier date, in which case only as of such date or period); and
• the representations and warranties of ONEOK and Merger Sub (other than Sections 4.2(a), 4.2(g), 4.10(b) and 4.10(c) of the Merger Agreement) shall be true and correct as of the date of the Merger Agreement and as of the closing date (except to the extent expressly made as of an earlier date, in which case only as of such date), except where the failure of such representations and warranties to be so true and correct (without giving effect to any limitation as to “materiality” or “material adverse effect” set forth in any individual such representation or warranty) would not, in the aggregate, reasonably be expected to have a material adverse effect on ONEOK.
• ONEOK’s performance or compliance in all material respects with all of its covenants, obligations or agreements required to be performed or complied with under the Merger Agreement prior to the Effective Time; and
• ONEOK having delivered to Magellan a certificate of a duly authorized officer certifying the matters of the immediately preceding bullets.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Conditions to the Completion of the Merger, page 126'}, {'quote': 'Each of ONEOK and Magellan submitted the required notification and furnished information to the FTC and the DOJ and the HSR Act waiting period expired at 11:59 p.m., Eastern Time, on June 26, 2023.', 'location': 'fs42023a1_oneokinc.htm, SUMMARY — Regulatory Approvals, pages 17–18'}, {'quote': 'Parent acknowledges and agrees that in no event is the receipt or availability of any funds or financing (including the Debt Financing) by Parent or Merger Sub a condition to the Closing.', 'location': 'fs42023a1_oneokinc.htm, Annex A — Agreement and Plan of Merger, Section 4.22(c), page A-30'}], 'event_status': [{'quote': 'As filed with the Securities and Exchange Commission on July 10, 2023', 'location': 'fs42023a1_oneokinc.htm, registration statement cover'}, {'quote': 'Amendment No. 1
to
FORM S-4', 'location': 'fs42023a1_oneokinc.htm, registration statement cover'}, {'quote': 'On May 14, 2023, ONEOK and Magellan entered into an Agreement and Plan of Merger (the “Merger Agreement”) with Otter Merger Sub, LLC, a wholly owned subsidiary of ONEOK (“Merger Sub”), pursuant to which Merger Sub will merge with and into Magellan (the “merger”), with Magellan surviving the merger as a direct wholly owned subsidiary of ONEOK.', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}, {'quote': 'However, neither ONEOK nor Magellan can predict the actual date on which the merger will be completed, or if the merger will be completed at all, because completion of the merger is subject to conditions and factors outside the control of either company.', 'location': 'fs42023a1_oneokinc.htm, QUESTIONS AND ANSWERS ABOUT THE MERGER AND SPECIAL MEETINGS — When is the merger expected to be completed?, page xvi'}], 'security_description': [{'quote': 'In the merger, the holders of common units representing a limited partner interest in Magellan (each such common unit, a “Magellan Unit,” and each such holder, a “Magellan unitholder”) will receive, for each Magellan Unit that they own as of immediately prior to the effective time of the merger (the “Effective Time”), a combination of (i) $25.00 in cash (the “Cash Consideration”), and (ii) 0.667 (the “Exchange Ratio”) of a share of common stock of ONEOK, par value $0.01 per share (“ONEOK Common Stock”; such consideration, the “Equity Consideration” and together with the Cash Consideration, the “Merger Consideration”).', 'location': 'fs42023a1_oneokinc.htm, joint proxy statement/prospectus, opening letter'}, {'quote': 'all Magellan Units owned immediately prior to the Effective Time by Magellan or its wholly owned subsidiaries or by ONEOK or its wholly owned subsidiaries (the “Excluded Units”) will automatically be canceled and cease to exist without any conversion thereof and no consideration will be delivered in exchange therefor;', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Merger Consideration, page 102'}, {'quote': 'Each award of phantom units and performance phantom units of Magellan will be treated as follows: (i) at the Effective Time, each Magellan RSU Award, whether vested or unvested, that is outstanding immediately prior to the Effective Time, will be assumed by ONEOK and converted into a phantom unit award relating to a number of shares of ONEOK Common Stock equal to the number of Magellan Units subject to such Magellan RSU Award immediately prior to the Effective Time multiplied by the Equity Exchange Ratio, rounded up or down to the nearest whole share of ONEOK Common Stock and otherwise subject to the same terms and conditions of such Magellan RSU Award and (ii) at the Effective Time, each Magellan PSU Award, whether vested or unvested, that is outstanding immediately prior to the Effective Time, will be assumed by ONEOK and converted into a phantom unit award relating to a number of shares of ONEOK Common Stock equal to the number of Magellan Units subject to such Magellan PSU Award immediately prior to the Effective Time, assuming achievement of the applicable performance based vesting condition at the maximum level, multiplied by the Equity Exchange Ratio, rounded up or down to the nearest whole share of ONEOK Common Stock and otherwise subject to the same terms and conditions of such Magellan PSU Award (other than the performance-based vesting conditions); provided, however, such assumed award or the relevant portion thereof will be paid to the holder thereof no later than March 15th of the year following the calendar year in which any substantial risk of forfeiture, within the meaning of Internal Revenue Code Section 409A, lapses with respect to such assumed award or the relevant portion thereof.', 'location': 'fs42023a1_oneokinc.htm, SUMMARY — Treatment of Magellan Equity Awards, page 6'}], 'effective_date': [{'quote': 'The closing of the merger will take place on the second business day after the conditions set forth in the Merger Agreement have been satisfied or waived (other than those conditions that by their nature are to be satisfied at the closing, but subject to the satisfaction or waiver of such conditions), or such other time as ONEOK and Magellan will mutually agree.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Completion and Effectiveness of the Merger, page 101'}, {'quote': 'On the closing date, Magellan will file a certificate of merger with the Secretary of State of the State of Delaware, executed in accordance with and containing such information as is required by the Delaware Partnership Act and the Delaware Limited Liability Company Act. The merger will become effective upon such filing of the certificate of merger with the Secretary of State of the State of Delaware, or at such later date and time as agreed by ONEOK and Magellan and as specified in the certificate of merger.', 'location': 'fs42023a1_oneokinc.htm, THE MERGER AGREEMENT — Completion and Effectiveness of the Merger, page 101'}, {'quote': 'Subject to the satisfaction or, to the extent permissible under applicable law, waiver of the closing conditions described under “The Merger Agreement — Conditions to the Completion of the Merger,” including the approval of the Merger Proposal and the Stock Issuance Proposal, the merger is expected to close in the third quarter of 2023.', 'location': 'fs42023a1_oneokinc.htm, QUESTIONS AND ANSWERS ABOUT THE MERGER AND SPECIAL MEETINGS — When is the merger expected to be completed?, page xvi'}], 'available_options': [{'quote': 'At the Effective Time, each Magellan Unit (other than Magellan Units owned immediately prior to the Effective Time by Magellan or its wholly owned subsidiaries or by ONEOK or its wholly owned subsidiaries (the “Excluded Units”)) will automatically be converted into the right to receive:
• 0.667 duly authorized and validly issued shares of ONEOK Common Stock; and
• $25.00 in cash.', 'location': 'fs42023a1_oneokinc.htm, SUMMARY — Merger Consideration, pages 1–2'}], 'default_option': [], 'election_deadline': []}

{'acquirer': [{'quote': 'This Agreement and Plan of Merger, dated as of May 9, 2023 (this “Agreement”), is made and entered into by and among OmniLit Acquisition Corp., a Delaware corporation (“OmniLit”), Optics Merger Sub Inc., a Delaware corporation and a direct wholly-owned subsidiary of OmniLit (“Merger Sub”), and Syntec Optics, Inc., a Delaware corporation (the “Company”).', 'location': 'EX-2.1, Agreement and Plan of Merger'}, {'quote': 'Merger Sub will merge with and into the Company, the separate corporate existence of Merger Sub will cease and the Company will be the surviving corporation and a wholly owned subsidiary of OmniLit', 'location': 'EX-2.1, Recitals'}], 'target': [{'quote': 'Syntec Optics, Inc., a Delaware corporation (the “Company”)', 'location': 'EX-2.1, Agreement and Plan of Merger'}, {'quote': 'Merger Sub will merge with and into the Company, the separate corporate existence of Merger Sub will cease and the Company will be the surviving corporation and a wholly owned subsidiary of OmniLit', 'location': 'EX-2.1, Recitals'}], 'consideration_type': [{'quote': 'upon the Effective Time (as defined below), all shares of Company Common Stock (as defined below) will be converted into the right to receive shares of OmniLit Post-Merger Class A Common Stock (as defined below) as set forth in this Agreement;', 'location': 'EX-2.1, Recitals'}, {'quote': 'Holders of Syntec Optics common stock will have the contingent right to receive up to 26,000,000 shares of New Syntec Optics common stock in the aggregate (“Contingent Earnout Shares”)', 'location': 'S-4/A, Proposal No. 1 — The Business Combination Proposal — Consideration to Syntec Optics Holders in the Business Combination, page 82'}, {'quote': 'The Contingent Earnout shares will vest upon OmniLit Common Stock achieving the following stock trading price thresholds (the “Contingent Earnout Trigger Price”) following the Closing: one-third (1/3rd) at $12.50 per share, one-third (1/3rd) at $14.00 per share, and one-third (1/3rd) at $15.50 per share (as adjusted for stock splits, stock dividends, reorganizations, recapitalizations and the like). The Contingent Earnout shares which remain unvested as of the date five (5) years from the Closing (the “Earnout Period”) will be deemed cancelled and no longer subject to vesting.', 'location': 'EX-2.1, Section 3.4(b), page 20'}, {'quote': 'The achievement of the Contingent Earnout Trigger Price will be based on either (a) the closing price of the OmniLit Common Stock equaling or exceeding the specified threshold for twenty (20) trading days within any thirty (30)-trading day period, or (b) upon the consummation of a change of control transaction in which the per share price implied in such change of control transaction is greater than or equal to the applicable threshold.', 'location': 'EX-2.1, Section 3.4(b), page 20'}], 'cash_consideration': [{'quote': 'there being no cash at close distribution requirement (for the avoidance of doubt, meaning no cash distribution to Syntec Optics stockholders) at Closing to Syntec Optics stockholders', 'location': 'S-4/A, Preliminary Proxy Statement/Prospectus'}], 'stock_exchange_ratio': [{'quote': '“Exchange Ratio” means a fraction equal to (i) (a) the Aggregate Merger Consideration divided by (b) ten dollars ($10.00), divided by (ii) the Aggregate Fully Diluted Company Common Shares as calculated pursuant to the definition of “Aggregate Fully Diluted Company Common Shares” herein and set forth in the Company Certificate or, if applicable, the Revised Company Certificate, delivered by the Company to the OmniLit pursuant to Section 3.3(c).', 'location': 'EX-2.1, Section 1.1, page 6'}, {'quote': '“Aggregate Merger Consideration” means (i) $325,000,000, minus (ii) the Company Net Debt Amount, each calculated as set forth in the Company Certificate or, if applicable, the Revised Company Certificate, in each case delivered by the Company to the OmniLit pursuant to Section 3.3(c).', 'location': 'EX-2.1, Section 1.1, page 3'}, {'quote': '“Company Net Debt Amount” means, as calculated immediately prior to the Closing, an amount equal to (i) the aggregate indebtedness for borrowed money of the Company and its Subsidiaries minus (ii) Cash and Cash Equivalents.', 'location': 'EX-2.1, Section 1.1, page 5'}, {'quote': 'Each holder of shares of Company Common Stock as of immediately prior to the Effective Time (other than in respect of (y) Treasury Shares and (z) Dissenting Shares, shall be converted into the right to receive a portion of the Aggregate Merger Consideration equal to (i) the Exchange Ratio, multiplied by (ii) the number of shares of Company Common Stock held by such holder as of immediately prior to the Effective Time, with fractional shares rounded down to the nearest whole share.', 'location': 'EX-2.1, Section 3.2(a), page 18'}, {'quote': '“OmniLit Post-Merger Class A Common Stock” means the Class A common stock, par value $0.0001 per share, of OmniLit, authorized under the OmniLit Post-Merger Charter.', 'location': 'EX-2.1, Section 1.1, page 9'}], 'shareholder_vote_date': [{'quote': 'the annual meeting will be held on [●] at [●] Eastern Time.', 'location': 'S-4/A, Questions and Answers About the Proposals, page 8'}], 'closing_conditions': [{'quote': 'The obligations of OmniLit, Merger Sub and the Company to consummate, or cause to be consummated, the Merger is subject to the satisfaction of the following conditions, any one or more of which may be waived in writing by all of such parties:', 'location': 'EX-2.1, Section 9.1, page 60'}, {'quote': '(a) The OmniLit Stockholder Approval shall have been obtained;
(b) The Company Stockholder Approvals shall have been obtained;
(c) The Registration Statement shall have become effective under the Securities Act and no stop order suspending the effectiveness of the Registration Statement shall have been issued and no proceedings for that purpose shall have been initiated or threatened by the SEC and not withdrawn;
(d) The waiting period or periods under the HSR Act applicable to the transactions contemplated by this Agreement and the Ancillary Agreements shall have expired or been terminated;', 'location': 'EX-2.1, Section 9.1, page 60'}, {'quote': '(e) There shall not be in force any Governmental Order, statute, rule or regulation enjoining or prohibiting the consummation of the Merger; provided, that the Governmental Authority issuing such Governmental Order has jurisdiction over the parties hereto with respect to the transactions contemplated hereby;
(f) OmniLit shall have at least $5,000,001 of net tangible assets immediately prior to or upon the consummation of the Business Combination (as determined in accordance with Rule 3a51-1(g)(1) of the Exchange Act); and
(g) The shares of OmniLit Post-Merger Class A Common Stock to be issued in connection with the Merger shall have been approved for listing on the Stock Exchange, and, immediately following the Effective Time, OmniLit shall satisfy any applicable continuing listing requirements of the Stock Exchange, and OmniLit shall not have received any notice of non-compliance therewith that has not been cured or would not be cured at or immediately following the Effective Time.', 'location': 'EX-2.1, Section 9.1, pages 60–61'}, {'quote': 'The obligations of OmniLit and Merger Sub to consummate, or cause to be consummated, the Merger are subject to the satisfaction of the following additional conditions, any one or more of which may be waived in writing by OmniLit and Merger Sub:', 'location': 'EX-2.1, Section 9.2, page 61'}, {'quote': '(a) (i) The Company Fundamental Representations shall be true and correct in all material respects, in each case as of the Closing Date, except with respect to such representations and warranties which speak as to an earlier date, which representations and warranties shall be true and correct in all material respects at and as of such date, except for changes after the date of this Agreement which are contemplated or expressly permitted by this Agreement or the Ancillary Agreements, and (ii) each of the representations and warranties of the Company contained in this Agreement other than the Company Fundamental Representations (disregarding any qualifications and exceptions contained therein relating to materiality, material adverse effect and Company Material Adverse Effect or any similar qualification or exception) shall be true and correct as of the Closing Date, except with respect to such representations and warranties which speak as to an earlier date, which representations and warranties shall be true and correct at and as of such date, except for, in each case in this clause (ii), inaccuracies or omissions that have not had, and would not, individually or in the aggregate, reasonably be expected to have a Company Material Adverse Effect;
(b) Each of the covenants of the Company to be performed as of or prior to the Closing shall have been performed in all material respects;
(c) The Company shall have delivered, or caused to be delivered, to OmniLit the documents set forth in Section 2.4(a); and
(d) No Company Material Adverse Effect shall have occurred between the date of this Agreement and the Closing.', 'location': 'EX-2.1, Section 9.2, page 61'}, {'quote': 'The obligation of the Company to consummate, or cause to be consummated, the Merger is subject to the satisfaction of the following additional conditions, any one or more of which may be waived in writing by the Company:', 'location': 'EX-2.1, Section 9.3, page 61'}, {'quote': '(a) (i) The representations and warranties of OmniLit and Merger Sub contained in Section 5.1, Section 5.2, Section 5.3(a), Section 5.3(b), Section 5.12 and Section 5.14 shall be true and correct in all material respects as of the Closing Date, except with respect to such representations and warranties that speak as of an earlier date, which representations and warranties shall be true in all material respects at and as of such date, and (ii) each of the representations and warranties of OmniLit contained in this Agreement (disregarding any qualifications and exceptions contained therein relating to materiality, material adverse effect or any similar qualification or exception) shall be true and correct in all material respects, in each case as of the Closing Date, except with respect to such representations and warranties which speak as to an earlier date, which representations and warranties shall be true and correct in all material respects at and as of such date, except for in each case in this clause (ii), inaccuracies or omissions that have not had, and would not, individually or in the aggregate, reasonably be expected to have a material adverse effect on OmniLit;', 'location': 'EX-2.1, Section 9.3, page 61'}, {'quote': '(b) Each of the covenants of OmniLit to be performed as of or prior to the Closing shall have been performed in all material respects;
(c) The certificate of incorporation of OmniLit and bylaws of OmniLit shall have been amended and restated to be substantially in the forms of Exhibit C and Exhibit D, respectively, attached hereto; and
(d) OmniLit shall have delivered, or caused to be delivered, to the Company the documents set forth in Section 2.4(b).', 'location': 'EX-2.1, Section 9.3, page 62'}, {'quote': 'The consummation of the Business Combination is contingent upon approval from Nasdaq of the listing of the common stock and warrants, and these conditions are not waivable.', 'location': 'S-4/A, Preliminary Proxy Statement/Prospectus'}], 'event_status': [{'quote': 'On May 9, 2023, Benchmark updated its financial analysis and confirmed its previously-rendered verbal opinion by delivery of Benchmark’s written opinion addressed to the Special Committee that, as of the date thereof and based on the assumption made, procedures followed, matters considered, limitations of the review undertaken and qualifications contained therein, the consideration to be paid by OmniLit to the Syntec Optics stockholders in the Business Combination pursuant to the Business Combination Agreement was fair to OmniLit from a financial point of view. The Business Combination Agreement was then executed by OmniLit and Syntec Optics.', 'location': 'S-4/A, Proposal No. 1 — Background of the Business Combination, page 105'}, {'quote': 'As described in this proxy statement/prospectus, OmniLit’s stockholders are being asked to consider a vote upon the Business Combination, among other items.', 'location': 'S-4/A, Preliminary Proxy Statement/Prospectus'}, {'quote': 'This agreement is pending approval by the OmniLit shareholders.', 'location': 'S-4/A, Syntec Optics, Inc., Notes to Consolidated Financial Statements, Note 16 — Subsequent Event, page F-71'}], 'security_description': [{'quote': '“Company Common Stock” means the shares of common stock, par value $0.01 per share, of the Company.', 'location': 'EX-2.1, Section 1.1, page 4'}, {'quote': 'At the Effective Time, by virtue of the Merger and without any action on the part of any holder of Company Common Stock or any other party each share of Company Common Stock that is issued and outstanding immediately prior to the Effective Time, (other than (i) any shares of Company Common Stock held in the treasury of the Company, which treasury shares shall be cancelled as part of the Merger and shall not constitute “Company Common Stock” hereunder (each such share, a “Treasury Share”), and (ii) any Dissenting Shares (as defined in Section 3.6)) shall be cancelled and converted into the right to receive the applicable portion of the Aggregate Merger Consideration as determined pursuant to Section 3.2(a).', 'location': 'EX-2.1, Section 3.1(a), page 18'}], 'effective_date': [{'quote': 'The Merger shall become effective at the time when the Merger Certificate has been accepted for filing by the Secretary of State of the State of Delaware, or at such later time as may be agreed by OmniLit and the Company in writing and specified in each of the Merger Certificate (the “Effective Time”).', 'location': 'EX-2.1, Section 2.3(b), page 15'}, {'quote': 'OmniLit, Merger Sub, and the Company shall cause the Merger Certificate to be executed and duly submitted for filing on the Closing Date with the Secretary of State of the State of Delaware in accordance with the applicable provisions of the DGCL.', 'location': 'EX-2.1, Section 2.3(b), page 15'}], 'available_options': [{'quote': 'At the Effective Time, by virtue of the Merger and without any action on the part of any holder of Company Common Stock or any other party each share of Company Common Stock that is issued and outstanding immediately prior to the Effective Time, (other than (i) any shares of Company Common Stock held in the treasury of the Company, which treasury shares shall be cancelled as part of the Merger and shall not constitute “Company Common Stock” hereunder (each such share, a “Treasury Share”), and (ii) any Dissenting Shares (as defined in Section 3.6)) shall be cancelled and converted into the right to receive the applicable portion of the Aggregate Merger Consideration as determined pursuant to Section 3.2(a).', 'location': 'EX-2.1, Section 3.1(a), page 18'}], 'default_option': [], 'election_deadline': []}
